-- =============================================================
-- Cartelera (versión React) — Esquema
-- Supabase > SQL Editor: ejecutar en orden 01, 02, 03.
-- =============================================================

-- -------------------------------------------------------------
-- eventos: las mismas columnas que src/data/eventos.json, para que
-- los componentes no cambien. "generated by default as identity" =
-- Postgres asigna el id (1, 2, 3...) como lo haría el servidor.
-- -------------------------------------------------------------
create table public.eventos (
  id          bigint generated by default as identity primary key,
  titulo      text not null,
  descripcion text not null,
  categoria   text not null,
  fecha       text not null,          -- texto libre, igual que en el JSON
  lugar       text not null,
  precio      integer not null default 0 check (precio >= 0),
  cupos       integer not null check (cupos > 0),
  imagen      text not null,
  alt         text not null,
  destacado   boolean not null default false,
  creado_en   timestamptz not null default now()
);

-- -------------------------------------------------------------
-- profiles: el ROL de cada usuario. auth.users lo administra Supabase
-- (email, contraseña cifrada) y no se le agregan columnas: el rol va
-- en una tabla nuestra, enlazada por el mismo id.
-- -------------------------------------------------------------
create table public.profiles (
  id     uuid primary key references auth.users(id) on delete cascade,
  nombre text,
  rol    text not null default 'usuario' check (rol in ('usuario', 'admin'))
);

-- Cada usuario nuevo (registro o "Add user" en el panel) recibe su perfil
-- con rol 'usuario'. Volver admin a alguien es una decisión del servidor:
--   update public.profiles set rol = 'admin' where id = '<uuid>';
create or replace function public.crear_perfil()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  insert into public.profiles (id, nombre)
  values (new.id, split_part(new.email, '@', 1));
  return new;
end;
$$;

create trigger on_auth_user_created
  after insert on auth.users
  for each row execute function public.crear_perfil();
